@push('scripts')<script>const overlay=document.getElementById('modalOverlay'),panel=document.getElementById('modalPanel');function openModal(){overlay.classList.remove('hidden');overlay.classList.add('flex');requestAnimationFrame(()=>panel.classList.add('scale-100'))}function closeModal(){window.location.href=@json(route('admin.blog.index'))}function addGalleryInput(){const i=document.createElement('input');i.type='file';i.name='gallery_images[]';i.accept='image/*';i.className='block w-full';document.getElementById('galleryInputs').appendChild(i)}@if(session('success'))showToast(@json(session('success')));@endif</script>@endpush
